import SwiftUI
import OSLog
import Foundation

/// Writes a clearly searchable startup trace to the device's unified log.
/// Native iOS .ips crash reports remain generated by iOS itself.
enum StartupDiagnostics {
    static let logger = Logger(
        subsystem: Bundle.main.bundleIdentifier ?? "com.anadolugalericilersitesi.app",
        category: "AnadoluOtogalericileriStartup"
    )

    static func install() {
        logger.notice("Anadolu Otogalericileri launch started; version=\(Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "unknown", privacy: .public); build=\(Bundle.main.infoDictionary?["CFBundleVersion"] as? String ?? "unknown", privacy: .public)")
        NSSetUncaughtExceptionHandler { exception in
            let reason = exception.reason ?? "No exception reason"
            StartupDiagnostics.logger.fault(
                "Uncaught Objective-C exception: \(exception.name.rawValue, privacy: .public) — \(reason, privacy: .public)"
            )
            UserDefaults.standard.set(
                "\(exception.name.rawValue): \(reason)",
                forKey: "last_uncaught_exception"
            )
            UserDefaults.standard.synchronize()
        }

        if let previousException = UserDefaults.standard.string(forKey: "last_uncaught_exception") {
            logger.error("Previous uncaught Objective-C exception recorded: \(previousException, privacy: .public)")
            UserDefaults.standard.removeObject(forKey: "last_uncaught_exception")
        }
    }
}

@main
struct iOSApp: App {
    init() {
        StartupDiagnostics.install()
    }

    var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}
